	private static final String WRITER_TYPE = "org.eclipse.rdf4j.sail.lmdb.frontier.FrontierPayloadBlockWriter";
	private static final String READER_TYPE = "org.eclipse.rdf4j.sail.lmdb.frontier.FrontierPayloadBlockReader";
	private static final String BLOCK_TYPE = "org.eclipse.rdf4j.sail.lmdb.frontier.FrontierPayloadBlock";
	private static final String PAYLOAD_EXCEPTION_TYPE = "org.eclipse.rdf4j.sail.lmdb.frontier.FrontierPayloadException";

	private static final int MAGIC = 0x524a4642; // RJFB
	private static final int LEGACY_VERSION = 1;
