			Method writeBlock = accessible(writerType.getDeclaredMethod("writeBlock", int.class, long[].class));
			Method finish = accessible(writerType.getDeclaredMethod("finish"));
			assertEquals(FrontierPayloadDescriptor.class, finish.getReturnType());
			Method readBlock = accessible(readerType.getDeclaredMethod("readBlock"));
			assertEquals(blockType, readBlock.getReturnType());
			Method kind = accessible(blockType.getDeclaredMethod("kind"));
			Method generation = accessible(blockType.getDeclaredMethod("generation"));
